steps.code:
# A plain event
@openpanel_tracker.track('signup_completed', payload: { plan: 'free' })

# An event attached to a known user
@openpanel_tracker.track(
  'invoice_paid',
  profile_id: current_user.id.to_s,
  payload: { amount: 49 }
)

# Build a profile
identify_user = OpenPanel::SDK::IdentifyUser.new
identify_user.profile_id = current_user.id.to_s
identify_user.email = current_user.email
identify_user.first_name = current_user.first_name
identify_user.last_name = current_user.last_name
identify_user.properties = { tier: 'premium', company: 'Acme Inc' }

@openpanel_tracker.identify(identify_user)

# Counters on the profile
@openpanel_tracker.increment_property(identify_user, 'visits', 1)
@openpanel_tracker.decrement_property(identify_user, 'credits', 1)

# Revenue
@openpanel_tracker.revenue(
  user: identify_user,
  amount: 49,
  properties: { currency: 'EUR' }
)
